const pipe = (...fns) => (value) => fns.reduce((result, fn) => fn(result), value);

const double = (n) => n * 2;
const addOne = (n) => n + 1;
const square = (n) => n * n;

console.log(pipe(double, addOne)(5));
console.log(pipe(addOne, double)(5));
console.log(pipe(square, double, addOne)(3));
console.log(pipe()(4));
